public class Solution {
    public static void main(String[] args) {
        long totalMb = 256;
        long freeMb = 238;
        long usedMb = totalMb - freeMb;
        double initialPct = ((double) usedMb / totalMb) * 100.0;

        System.out.printf("Initial Heap: Total = %d MB, Free = %d MB, Used = %d MB (%.1f%%)%n",
                totalMb, freeMb, usedMb, initialPct);
        System.out.println("Allocating objects to reach 30% threshold...");

        long simulatedUsed = 80;
        double thresholdPct = ((double) simulatedUsed / totalMb) * 100.0;
        System.out.printf("Threshold Reached: Heap Used = %d MB / %d MB (%.2f%%)%n",
                simulatedUsed, totalMb, thresholdPct);
        System.out.println("Monitoring alert triggered successfully.");
    }
}

